import unittest
from candidate import add

class TestAddFunction(unittest.TestCase):
    def test_add_positive_numbers(self):
        self.assertEqual(add(2, 3), 5)

    def test_add_negative_numbers(self):
        self.assertEqual(add(-2, -3), -5)

    def test_add_mixed_numbers(self):
        self.assertEqual(add(-2, 3), 1)

    def test_add_zero(self):
        self.assertEqual(add(0, 5), 5)
        self.assertEqual(add(0, 0), 0)

    def test_add_with_floats(self):
        self.assertAlmostEqual(add(2.5, 3.5), 6.0)

    def test_add_large_integers(self):
        large = 10**100
        self.assertEqual(add(large, large), 2 * large)
        self.assertEqual(add(-large, -large), -2 * large)

    def test_add_boolean_values(self):
        self.assertEqual(add(True, False), 1)
        self.assertEqual(add(False, False), 0)

    def test_add_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(None, 1)
        with self.assertRaises(TypeError):
            add(1, None)

    def test_add_missing_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(1)

    def test_add_extra_argument_raises_type_error(self):
        with self.assertRaises(TypeError):
            add(1, 2, 3)

    def test_add_with_keyword_arguments(self):
        self.assertEqual(add(x=4, y=5), 9)

    def test_add_with_wrong_keyword_arguments(self):
        with self.assertRaises(TypeError):
            add(a=1, b=2)

    def test_add_pure_function(self):
        result1 = add(7, 8)
        result2 = add(7, 8)
        self.assertEqual(result1, result2)
        self.assertEqual(result1, 15)

if __name__ == "__main__":
    unittest.main()
